     6	<title>Calculator</title>
     7	<style>
     8	  * { box-sizing: border-box; }
     9	  body {
    10	    margin: 0;
    11	    min-height: 100vh;
    12	    display: flex;
    13	    align-items: center;
    14	    justify-content: center;
    15	    background: #e9ebef;
    16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    17	  }
    18	  .app {
    19	    width: 320px;
    20	    max-width: calc(100vw - 32px);
    21	    margin: 16px 0;
    22	    display: flex;
    23	    flex-direction: column;
    24	    gap: 16px;
    25	  }
    26	  .calc {
    27	    padding: 16px;
    28	    border-radius: 20px;
    29	    background: #1f2229;
    30	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
    31	  }
    32	  .display {
    33	    height: 88px;
    34	    margin-bottom: 16px;
    35	    padding: 0 12px;
    36	    display: flex;
    37	    align-items: flex-end;
    38	    justify-content: flex-end;
    39	    overflow: hidden;
    40	    color: #fff;
    41	    font-size: 48px;
    42	    font-weight: 300;
    43	    white-space: nowrap;
    44	    font-variant-numeric: tabular-nums;
    45	  }
    46	  .keys {
    47	    display: grid;
    48	    grid-template-columns: repeat(4, 1fr);
    49	    gap: 10px;
    50	  }
    51	  button {
    52	    height: 64px;
    53	    border: 0;
    54	    border-radius: 14px;
    55	    font: inherit;
    56	    font-size: 24px;
    57	    color: #fff;
    58	    background: #3a3f4a;
    59	    cursor: pointer;
    60	  }
    61	  button:hover { filter: brightness(1.12); }
    62	  button:active { filter: brightness(0.9); }
    63	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
    64	  .op { background: #f59e0b; }
    65	  .op.active { background: #fff; color: #f59e0b; }
    66	  .fn { background: #a5a9b3; color: #1f2229; }
    67	  .wide { grid-column: span 2; }
    68	  .tape-panel {
    69	    padding: 12px 16px 8px;
    70	    border-radius: 20px;
    71	    background: #1f2229;
    72	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
    73	    color: #fff;
    74	  }
    75	  .tape-head {
    76	    display: flex;
    77	    align-items: center;
    78	    justify-content: space-between;
    79	    margin-bottom: 4px;
    80	  }
    81	  .tape-title { font-size: 14px; color: #a5a9b3; }
    82	  .tape-head button {
    83	    height: 28px;
    84	    padding: 0 12px;
    85	    border-radius: 8px;
    86	    font-size: 14px;
    87	  }
    88	  .tape {
    89	    max-height: 240px;
    90	    overflow-y: auto;
    91	  }
