    95	    text-align: right;
    96	    font-variant-numeric: tabular-nums;
    97	  }
    98	  .tape-row:first-child { border-top: 0; }
    99	  .tape-expr { font-size: 14px; color: #a5a9b3; overflow-wrap: anywhere; }
