   103	<body>
   104	<div class="app">
   105	<div class="calc">
   106	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
   107	  <div class="keys">
   108	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open parenthesis">(</button>
   109	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close parenthesis">)</button>
   110	
   111	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
   112	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
   113	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
   114	
   115	    <button data-testid="key-7" data-digit="7">7</button>
   116	    <button data-testid="key-8" data-digit="8">8</button>
   117	    <button data-testid="key-9" data-digit="9">9</button>
   118	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
   119	
   120	    <button data-testid="key-4" data-digit="4">4</button>
   121	    <button data-testid="key-5" data-digit="5">5</button>
   122	    <button data-testid="key-6" data-digit="6">6</button>
   123	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
   124	
   125	    <button data-testid="key-1" data-digit="1">1</button>
   126	    <button data-testid="key-2" data-digit="2">2</button>
   127	    <button data-testid="key-3" data-digit="3">3</button>
   128	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
   129	
   130	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
   131	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
   132	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
   133	  </div>
   134	</div>
   135	<div class="tape-panel">
   136	  <div class="tape-head">
   137	    <span class="tape-title">History</span>
   138	    <button class="fn" data-testid="tape-clear">Clear</button>
   139	  </div>
   140	  <div class="tape" data-testid="calc-tape"></div>
   141	</div>
   142	</div>
   143	<script>
   144	(function () {
   145	  var display = document.querySelector('[data-testid="calc-display"]');
   146	  var opButtons = document.querySelectorAll('[data-op]');
   147	  var tape = document.querySelector('[data-testid="calc-tape"]');
   148	  var OP_SYMBOLS = { '+': '+', '-': '−', '*': '×', '/': '÷' };
   149	
   150	  // entry: string being typed, or null when showing a stored value.
   151	  // value: number currently shown when entry is null.
   152	  // operand: true when value came from ± or ) and is the next operand, like
   153	  // a typed entry, but further digits start a new entry instead of appending.
   154	  // groups: one saved { stored, op, tok } per open parenthesis, innermost last.
   155	  // tokens: the expression so far, for the tape. groupTok: index of the "("
   156	  // token when the operand is a just-closed group, whose tokens are already
   157	  // in the expression; otherwise null.
   158	  var state;
   159	
   160	  function reset() {
   161	    state = { entry: null, value: 0, stored: null, op: null, operand: false, error: false, groups: [],
   162	              tokens: [], groupTok: null };
   163	  }
   164	
   165	  // Add the operand being consumed to the expression, unless it is a closed
   166	  // group already written there.
   167	  function pushOperand(n) {
   168	    if (state.groupTok === null) state.tokens.push(formatValue(n));
   169	    state.groupTok = null;
   170	  }
   171	
   172	  function isOpToken(t) {
   173	    return t === '+' || t === '−' || t === '×' || t === '÷';
   174	  }
   175	
   176	  function joinTokens(tokens) {
   177	    var out = '';
   178	    for (var i = 0; i < tokens.length; i++) {
   179	      var t = tokens[i];
   180	      var prev = tokens[i - 1];
   181	      var tight = i === 0 || t === ')' || prev === '(' || prev === '-(';
   182	      out += (tight ? '' : ' ') + t;
   183	    }
   184	    return out;
   185	  }
   186	
   187	  function addTapeRow(expr, value) {
   188	    var row = document.createElement('div');
   189	    row.className = 'tape-row';
   190	    row.setAttribute('data-testid', 'tape-row');
   191	    var exprEl = document.createElement('div');
   192	    exprEl.className = 'tape-expr';
   193	    exprEl.setAttribute('data-testid', 'tape-expr');
   194	    exprEl.textContent = expr;
   195	    var resultEl = document.createElement('div');
   196	    resultEl.className = 'tape-result';
   197	    resultEl.setAttribute('data-testid', 'tape-result');
   198	    resultEl.setAttribute('data-value', String(value));
   199	    resultEl.textContent = formatValue(value);
   200	    row.appendChild(exprEl);
   201	    row.appendChild(resultEl);
   202	    tape.insertBefore(row, tape.firstChild);
   203	  }
   204	
   205	  function compute(a, op, b) {
   206	    switch (op) {
   207	      case '+': return a + b;
   208	      case '-': return a - b;
   209	      case '*': return a * b;
   210	      case '/': return a / b;
   211	    }
   212	    return b;
   213	  }
   214	
   215	  function currentNumber() {
   216	    return state.entry !== null ? parseFloat(state.entry) : state.value;
   217	  }
   218	
   219	  // Presentation only: round to at most 10 significant digits for the visible
   220	  // text. The stored value is never rounded, so chains stay exact.
   221	  // Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
   222	  function formatValue(n) {
   223	    if (n === 0) return '0';
   224	    var parts = Math.abs(n).toExponential(9).split('e');
   225	    var digits = parts[0].replace('.', '');
   226	    var exp = parseInt(parts[1], 10);
   227	    var sign = n < 0 ? '-' : '';
   228	    if (exp >= 10 || exp < -9) {
   229	      var mantissa = trimFraction(digits.charAt(0), digits.slice(1));
   230	      return sign + mantissa + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
   231	    }
   232	    if (exp >= 0) {
   233	      return sign + trimFraction(digits.slice(0, exp + 1), digits.slice(exp + 1));
   234	    }
   235	    return sign + trimFraction('0', new Array(-exp).join('0') + digits);
   236	  }
   237	
   238	  function trimFraction(intPart, frac) {
   239	    frac = frac.replace(/0+$/, '');
   240	    return frac ? intPart + '.' + frac : intPart;
   241	  }
   242	
   243	  function render() {
   244	    var text;
   245	    if (state.error) {
   246	      text = 'Error';
   247	    } else if (state.entry !== null) {
   248	      text = state.entry;
   249	    } else {
   250	      text = formatValue(state.value);
   251	    }
   252	    display.textContent = text;
   253	    display.setAttribute('data-value', state.error ? 'NaN' : String(currentNumber()));
   254	    display.setAttribute('data-error', state.error ? 'true' : 'false');
   255	
   256	    var len = text.length;
   257	    display.style.fontSize = len > 16 ? '20px' : len > 12 ? '28px' : len > 9 ? '36px' : '48px';
   258	
   259	    for (var i = 0; i < opButtons.length; i++) {
   260	      var b = opButtons[i];
   261	      b.classList.toggle('active', state.entry === null && !state.operand && state.op === b.getAttribute('data-op'));
   262	    }
   263	  }
   264	
   265	  // A new entry right after ) replaces the group's result, so the group
   266	  // leaves the expression too.
   267	  function dropGroupOperand() {
   268	    if (state.groupTok === null) return;
   269	    state.tokens.length = state.groupTok;
   270	    state.groupTok = null;
   271	  }
   272	
   273	  // In the error state every key except clear is ignored.
   274	  function inputDigit(d) {
   275	    if (state.error) return;
   276	    dropGroupOperand();
   277	    state.operand = false;
   278	    if (state.entry === null || state.entry === '0') {
   279	      state.entry = d;
   280	    } else if (state.entry === '-0') {
   281	      state.entry = '-' + d;
   282	    } else {
   283	      state.entry += d;
   284	    }
   285	  }
   286	
   287	  function inputDot() {
   288	    if (state.error) return;
   289	    dropGroupOperand();
   290	    state.operand = false;
   291	    if (state.entry === null) {
   292	      state.entry = '0.';
   293	    } else if (state.entry.indexOf('.') === -1) {
   294	      state.entry += '.';
   295	    }
   296	  }
   297	
   298	  // ± acts on the shown number at once. A typed entry keeps its text,
   299	  // so 0 ± 5 gives -5.
   300	  function inputSign() {
   301	    if (state.error) return;
   302	    if (state.entry !== null) {
   303	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
   304	    } else {
   305	      state.value = -state.value;
   306	      state.operand = true;
   307	      if (state.groupTok !== null) {
   308	        state.tokens[state.groupTok] = state.tokens[state.groupTok] === '(' ? '-(' : '(';
   309	      }
   310	    }
   311	  }
   312	
   313	  function setResult(n) {
   314	    if (!isFinite(n)) {
   315	      reset();
   316	      state.error = true;
   317	      return;
   318	    }
   319	    state.value = n;
   320	  }
   321	
   322	  // Immediate execution, strictly left to right, no operator precedence:
   323	  // an operator key first applies the operation already waiting, so the
   324	  // display always shows a real running result. 2 + 3 × 4 = is 20, not 14.
   325	  function inputOp(op) {
   326	    if (state.error) return;
   327	    if (state.entry !== null || state.operand) {
   328	      var n = currentNumber();
   329	      state.entry = null;
   330	      state.operand = false;
   331	      pushOperand(n);
   332	      if (state.op !== null && state.stored !== null) {
   333	        setResult(compute(state.stored, state.op, n));
   334	        if (state.error) return;
   335	      } else {
   336	        state.value = n;
   337	      }
   338	    } else if (isOpToken(state.tokens[state.tokens.length - 1])) {
   339	      // A second operator in a row replaces the first.
   340	      state.tokens.pop();
   341	    } else {
   342	      state.tokens.push(formatValue(state.value));
   343	    }
   344	    state.stored = state.value;
   345	    state.op = op;
   346	    state.tokens.push(OP_SYMBOLS[op]);
   347	  }
   348	
   349	  // Finish the operation waiting at the current level, as = does.
   350	  function finishLevel() {
   351	    state.operand = false;
   352	    if (state.op === null) {
   353	      if (state.entry !== null) {
   354	        state.value = parseFloat(state.entry);
   355	        state.entry = null;
   356	      }
   357	      pushOperand(state.value);
   358	      return;
   359	    }
   360	    var b = currentNumber();
   361	    state.entry = null;
   362	    pushOperand(b);
   363	    var op = state.op;
   364	    state.op = null;
   365	    var a = state.stored;
   366	    state.stored = null;
   367	    setResult(compute(a, op, b));
   368	  }
   369	
   370	  // ( saves the waiting operation and starts a fresh one inside the group.
   371	  // Right after a number, ( multiplies it by the group: 2 ( 3 ) is 6.
   372	  function openGroup() {
   373	    if (state.error) return;
   374	    if (state.entry !== null || state.operand) {
   375	      inputOp('*');
   376	      if (state.error) return;
   377	    }
   378	    state.groups.push({ stored: state.stored, op: state.op, tok: state.tokens.length });
   379	    state.tokens.push('(');
   380	    state.entry = null;
   381	    state.value = 0;
   382	    state.stored = null;
   383	    state.op = null;
   384	    state.operand = false;
   385	  }
   386	
   387	  // ) finishes the group and hands its result back as the next operand.
   388	  function closeGroup() {
   389	    if (state.error || state.groups.length === 0) return;
   390	    finishLevel();
   391	    if (state.error) return;
   392	    var outer = state.groups.pop();
   393	    state.stored = outer.stored;
   394	    state.op = outer.op;
   395	    state.operand = true;
   396	    state.tokens.push(')');
   397	    state.groupTok = outer.tok;
   398	  }
   399	
   400	  // = closes any groups still open, then finishes the calculation.
   401	  // A calculation with at least one operator goes on the tape; the result
   402	  // then starts a fresh expression.
   403	  function equals() {
   404	    if (state.error) return;
   405	    while (state.groups.length > 0) {
   406	      closeGroup();
   407	      if (state.error) return;
   408	    }
   409	    finishLevel();
   410	    if (state.error) return;
   411	    if (state.tokens.some(isOpToken)) addTapeRow(joinTokens(state.tokens), state.value);
   412	    state.tokens = [];
   413	    state.groupTok = null;
   414	  }
   415	
   416	  document.querySelector('.keys').addEventListener('click', function (e) {
   417	    var btn = e.target.closest('button');
   418	    if (!btn) return;
   419	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
   420	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
   421	    else {
   422	      var action = btn.getAttribute('data-action');
   423	      if (action === 'dot') inputDot();
   424	      else if (action === 'sign') inputSign();
   425	      else if (action === 'lparen') openGroup();
   426	      else if (action === 'rparen') closeGroup();
   427	      else if (action === 'equals') equals();
   428	      else if (action === 'clear') reset();
   429	    }
   430	    render();
   431	  });
   432	
   433	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
   434	    tape.textContent = '';
   435	  });
   436	
   437	  document.addEventListener('keydown', function (e) {
   438	    if (e.ctrlKey || e.metaKey || e.altKey) return;
   439	    var k = e.key;
   440	    if (/^[0-9]$/.test(k)) inputDigit(k);
   441	    else if (k === '.' || k === ',') inputDot();
   442	    else if (k === '+' || k === '-' || k === '*' || k === '/') inputOp(k);
   443	    else if (k === '(') openGroup();
   444	    else if (k === ')') closeGroup();
   445	    else if (k === 'Enter' || k === '=') equals();
   446	    else if (k === 'Escape' || k === 'c' || k === 'C') reset();
   447	    else return;
   448	    e.preventDefault();
   449	    render();
   450	  });
   451	
   452	  reset();
   453	  render();
   454	})();
   455	</script>
   456	</body>
   457	</html>
